public class Main {
    static void slip(String name, int salary) {
        int pf = salary * 12 / 100;
        System.out.println(name + ": gross " + salary + ", PF " + pf + ", net " + (salary - pf));
    }

    public static void main(String[] args) {
        slip("Ravi", 30000);
        slip("Sita", 42000);
    }
}

