task.solution:
public class Main {
    static double average(int a, int b) {
        return (a + b) / 2.0;
    }

    static double average(int a, int b, int c) {
        return (a + b + c) / 3.0;
    }

    public static void main(String[] args) {
        System.out.println(average(70, 85) + " " + average(60, 70, 90));
    }
}

