project.solution:
public class Main {
    static double calc(double a, char op, double b) {
        return switch (op) {
            case '+' -> a + b;
            case '-' -> a - b;
            case '*' -> a * b;
            case '/' -> b == 0 ? 0 : a / b;
            default -> 0;
        };
    }

    public static void main(String[] args) {
        System.out.println(calc(12, '+', 3));
        System.out.println(calc(12, '/', 0));
        System.out.println(calc(7, '*', 6));
    }
}
